    assertAnalyzesTo(indexAnalyzer, "是々の", new String[] { "是", "ze", "々", "の", "no" }, new int[] { 0, 0, 1, 2, 2 }, new int[] { 1, 1, 2, 3, 3 }, new int[] { 1, 0, 1, 1, 0 });
