@Test
public void testCompletionQuery() throws IOException {
    assertAnalyzesTo(queryAnalyzer, "東京", new String[] { "東京", "toukyou" }, new int[] { 0, 0 }, new int[] { 2, 2 }, new int[] { 1, 0 });
    assertAnalyzesTo(queryAnalyzer, "東京都", new String[] { "東京", "toukyou", "都", "to" }, new int[] { 0, 0, 2, 2 }, new int[] { 2, 2, 3, 3 }, new int[] { 1, 0, 1, 0 });
    assertAnalyzesTo(queryAnalyzer, "ドラえもん", new String[] { "ドラえもん", "doraemon", "doraemonn" }, new int[] { 0, 0, 0 }, new int[] { 5, 5, 5 }, new int[] { 1, 0, 0 });
    assertAnalyzesTo(queryAnalyzer, "ソースコード", new String[] { "ソースコード", "soーsukoーdo" }, new int[] { 0, 0 }, new int[] { 6, 6 }, new int[] { 1, 0 });
    assertAnalyzesTo(queryAnalyzer, "反社会的勢力", new String[] { "反", "han", "hann", "社会", "syakai", "shakai", "的", "teki", "勢力", "seiryoku" }, new int[] { 0, 0, 0, 1, 1, 1, 3, 3, 4, 4 }, new int[] { 1, 1, 1, 3, 3, 3, 4, 4, 6, 6 }, new int[] { 1, 0, 0, 1, 0, 0, 1, 0, 1, 0 });
