   */
@Test
public void testStressPerFieldCodec() throws IOException {
    Directory dir = newDirectory(random());
    final int docsPerRound = 97;
    int numRounds = atLeast(1);
    for (int i = 0; i < numRounds; i++) {
        int num = TestUtil.nextInt(random(), 30, 60);
        IndexWriterConfig config = newIndexWriterConfig(random(), new MockAnalyzer(random()));
        config.setOpenMode(OpenMode.CREATE_OR_APPEND);
        IndexWriter writer = newWriter(dir, config);
        for (int j = 0; j < docsPerRound; j++) {
            final Document doc = new Document();
            for (int k = 0; k < num; k++) {
                FieldType customType = new FieldType(TextField.TYPE_NOT_STORED);
                customType.setTokenized(random().nextBoolean());
                customType.setOmitNorms(random().nextBoolean());
                Field field = newField("" + k, TestUtil.randomRealisticUnicodeString(random(), 128), customType);
                doc.add(field);
            }
            writer.addDocument(doc);
        }
        if (random().nextBoolean()) {
            writer.forceMerge(1);
        }
        writer.commit();
        assertEquals((i + 1) * docsPerRound, writer.getDocStats().maxDoc);
        writer.close();
    }
    dir.close();
}

@Test
@SuppressForbidden(reason = "Uses Path.toFile because ProcessBuilder requires it.")
public void testDeadlock() throws Exception {
    // pick random codec names for stress test in separate process:
    final Random rnd = RandomizedContext.current().getRandom();
    Set<String> avail;
    final String codecName = new ArrayList<>(avail = Codec.availableCodecs()).get(rnd.nextInt(avail.size()));
    final String pfName = new ArrayList<>(avail = PostingsFormat.availablePostingsFormats()).get(rnd.nextInt(avail.size()));
    final String dvfName = new ArrayList<>(avail = DocValuesFormat.availableDocValuesFormats()).get(rnd.nextInt(avail.size()));
    System.out.printf(Locale.ROOT, "codec: %s, pf: %s, dvf: %s%n", codecName, pfName, dvfName);
    List<String> args = new ArrayList<>();
    args.add(Paths.get(System.getProperty("java.home"), "bin", "java").toString());
    args.addAll(LuceneTestCase.getJvmForkArguments());
    args.addAll(List.of(getClass().getName(), codecName, pfName, dvfName));
    // Fork a separate JVM to reinitialize classes.
    final Path output = RandomizedTest.newTempFile(LifecycleScope.TEST);
    final Process p = new ProcessBuilder(args).redirectErrorStream(true).redirectOutput(output.toFile()).start();
    boolean success = false;
    try {
        if (p.waitFor(MAX_TIME_SECONDS * 2, TimeUnit.SECONDS)) {
            assertEquals("Process died abnormally?", 0, p.waitFor());
            success = true;
        } else {
            p.destroyForcibly().waitFor();
            fail("Process did not exit after 60 secs?");
        }
    } finally {
        if (!success) {
            System.out.println("Subprocess emitted the following output:");
            System.out.write(Files.readAllBytes(output));
        }
    }
}

