                if (rnd.nextBoolean()) {
                    int index = map.indexOf(key);
                    if (map.indexExists(index)) {
                        previousValue = map.indexReplace(index, value);
                    } else {
                        map.indexInsert(index, key, value);
                        previousValue = 0;
                    }
                } else {
                    previousValue = map.put(key, value);
                }
                assertEquals(other.put(key, value), ((previousValue) == 0) && !hadOldValue ? null : previousValue);
                assertEquals(value, map.get(key));
                assertEquals(value, map.indexGet(map.indexOf(key)));
                assertTrue(map.containsKey(key));
                assertTrue(map.indexExists(map.indexOf(key)));
            } else {
                assertEquals(other.containsKey(key), map.containsKey(key));
                int previousValue = map.containsKey(key) && rnd.nextBoolean() ? map.indexRemove(map.indexOf(key)) : map.remove(key);
                assertEquals(other.remove(key), ((previousValue) == 0) && !hadOldValue ? null : previousValue);
            }
            assertEquals(other.size(), map.size());
        }
    }
}

