@Test
@Nightly
public void testRescoreField() throws Exception {
    Map<Integer, float[]> vectors = new HashMap<>();
    Random random = random();
    int numVectors = atLeast(NUM_VECTORS);
    int numSegments = random.nextInt(2, 10);
    // Step 1: Index random vectors in quantized format
    try (IndexWriter writer = new IndexWriter(directory, config)) {
        for (int j = 0; j < numSegments; j++) {
            for (int i = 0; i < numVectors; i++) {
                float[] vector = randomFloatVector(VECTOR_DIMENSION, random);
                Document doc = new Document();
                int id = j * numVectors + i;
                doc.add(new IntField("id", id, Field.Store.YES));
                doc.add(new KnnFloatVectorField(FIELD, vector, VECTOR_SIMILARITY_FUNCTION));
                writer.addDocument(doc);
                vectors.put(id, vector);
                writer.flush();
            }
        }
    }
    // Step 2: Run TwoPhaseKnnVectorQuery with a random target vector
    try (IndexReader reader = DirectoryReader.open(directory)) {
        IndexSearcher searcher = new IndexSearcher(reader);
        float[] targetVector = randomFloatVector(VECTOR_DIMENSION, random);
        int k = 10;
        double oversample = random.nextFloat(1.5f, 3.0f);
        KnnFloatVectorQuery knnQuery = new KnnFloatVectorQuery(FIELD, targetVector, k + (int) (k * oversample));
        Query query = RescoreTopNQuery.createFullPrecisionRescorerQuery(knnQuery, targetVector, FIELD, k);
        TopDocs topDocs = searcher.search(query, k);
        // Step 3: Verify that TopDocs scores match similarity with unquantized vectors
        for (ScoreDoc scoreDoc : topDocs.scoreDocs) {
            Document retrievedDoc = searcher.storedFields().document(scoreDoc.doc);
            int id = retrievedDoc.getField("id").numericValue().intValue();
            float[] docVector = vectors.get(id);
            assert docVector != null : "Vector for id " + id + " not found";
            float expectedScore = VECTOR_SIMILARITY_FUNCTION.compare(targetVector, docVector);
            Assert.assertEquals("Score does not match expected similarity for doc ord: " + scoreDoc.doc + ", id: " + id, expectedScore, scoreDoc.score, 1e-5);
        }
    }
}

@Test
public void testEquality() {
    Explanation e1 = Explanation.match(1f, "an explanation");
    Explanation e2 = Explanation.match(1f, "an explanation", Explanation.match(1f, "a subexplanation"));
    Explanation e25 = Explanation.match(1f, "an explanation", Explanation.match(1f, "a subexplanation", Explanation.match(1f, "a subsubexplanation")));
    Explanation e3 = Explanation.match(1f, "an explanation");
    Explanation e4 = Explanation.match(2f, "an explanation");
    Explanation e5 = Explanation.noMatch("an explanation");
    Explanation e6 = Explanation.noMatch("an explanation", Explanation.match(1f, "a subexplanation"));
    Explanation e7 = Explanation.noMatch("an explanation");
    Explanation e8 = Explanation.match(1f, "another explanation");
    assertEquals(e1, e3);
    assertFalse(e1.equals(e2));
    assertFalse(e2.equals(e25));
    assertFalse(e1.equals(e4));
    assertFalse(e1.equals(e5));
    assertEquals(e5, e7);
    assertFalse(e5.equals(e6));
    assertFalse(e1.equals(e8));
    assertEquals(e1.hashCode(), e3.hashCode());
    assertEquals(e5.hashCode(), e7.hashCode());
}

