    expectThrows(IllegalArgumentException.class, () -> new FacetField("", "abc"));
    expectThrows(IllegalArgumentException.class, () -> new IntAssociationFacetField(17, null, new String[] { "abc" }));
    expectThrows(IllegalArgumentException.class, () -> new IntAssociationFacetField(17, "", new String[] { "abc" }));
