@Test
public void testReadonlyMonitorThrowsWhenCallingWriteRequests() throws IOException {
    Path indexDirectory = createTempDir();
    MonitorConfiguration writeConfig = new MonitorConfiguration().setIndexPath(indexDirectory, MonitorQuerySerializer.fromParser(MonitorTestBase::parse));
    // this will create the index
    Monitor writeMonitor = new Monitor(ANALYZER, writeConfig);
    writeMonitor.close();
    MonitorConfiguration config = new MonitorConfiguration().setDirectoryProvider(() -> FSDirectory.open(indexDirectory), MonitorQuerySerializer.fromParser(MonitorTestBase::parse), true);
    try (Monitor monitor = new Monitor(ANALYZER, config)) {
        TermQuery query = new TermQuery(new Term(FIELD, "test"));
        assertThrows(UnsupportedOperationException.class, () -> {
            monitor.register(new MonitorQuery("query1", query, query.toString(), Collections.emptyMap()));
        });
        assertThrows(UnsupportedOperationException.class, () -> {
            monitor.deleteById("query1");
        });
        assertThrows(UnsupportedOperationException.class, () -> {
            monitor.clear();
        });
    }
}

