    ValueSource v2 = new ByteKnnVectorFieldSource("knnByteField1");
    ByteVectorSimilarityFunction byteDenseVectorSimilarityFunction = new ByteVectorSimilarityFunction(VectorSimilarityFunction.EUCLIDEAN, v1, v2);
    assertThrows(AssertionError.class, () -> searcher.search(new FunctionQuery(byteDenseVectorSimilarityFunction), 10));
    v1 = new ConstKnnFloatValueSource(new float[] { 1.f, 2.f });
